import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.BWuWLRhz.js";const d=JSON.parse('{"title":"📝 更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":1784462256000}'),r={name:"guide/changelog.md"};function o(n,l,s,u,h,c){return e(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="📝-更新日志" tabindex="-1">📝 更新日志 <a class="header-anchor" href="#📝-更新日志" aria-label="Permalink to &quot;📝 更新日志&quot;">​</a></h1><p>各版本的下载地址见 <a href="https://github.com/XnneHangLab/yutto-uiya/releases" target="_blank" rel="noreferrer">GitHub Releases</a>。</p><h2 id="v2-2-1-2026-07-19" tabindex="-1">v2.2.1（2026-07-19） <a class="header-anchor" href="#v2-2-1-2026-07-19" aria-label="Permalink to &quot;v2.2.1（2026-07-19）&quot;">​</a></h2><p><strong>FFmpeg 路径修复与内核升级</strong></p><ul><li>修复自定义 FFmpeg 路径：环境检查与 serve 现在使用同一个可执行文件，不再依赖文件名必须为 <code>ffmpeg</code>（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/77" target="_blank" rel="noreferrer">#77</a>）；</li><li>音频-only mp3/flac 转码逻辑下沉到 uiya-yutto 内核的 <code>resolve_audio_save_codec</code>，前端不再显式覆盖编码（<a href="https://github.com/XnneHangLab/yutto-uiya/issues/74" target="_blank" rel="noreferrer">#74</a>）；</li><li>内核升级至 uiya-yutto 0.2.4；</li><li>项目以 AGPL-3.0-only 许可证发布。</li></ul><h2 id="v2-2-0-2026-07-18" tabindex="-1">v2.2.0（2026-07-18） <a class="header-anchor" href="#v2-2-0-2026-07-18" aria-label="Permalink to &quot;v2.2.0（2026-07-18）&quot;">​</a></h2><p><strong>迁移到常驻 yutto server</strong> —— 解析与下载不再逐次启动子进程抓日志，改由一个随应用 自动启停的后台 server 驱动，结构化事件实时回传。</p><ul><li>收藏夹 / 合集解析大幅提速，列表边解析边逐条平滑出现；</li><li>下载卡片显示阶段（解析中 / 写入附件 / 下载中 / 后处理中）与实时进度条 （百分比 · 已下载 / 总量 · 速率），不再需要去控制台看进度；</li><li>下载队列串行执行，显著降低触发 B 站风控的概率；</li><li>修复仅音频 MP3 / FLAC 下载在合并阶段必然失败的问题（现在自动转码）；</li><li>保存设置会自动重启 server，下载目录 / FFmpeg / Python 的修改立即生效；</li><li>内核升级至 uiya-yutto 0.2.1。</li></ul><div class="warning custom-block"><p class="custom-block-title">升级后需要知道的变化</p><ul><li><strong>画质菜单</strong>总是显示完整档位（最高 8K），实际画质下载时自动降级，选高了不会失败 —— 详见 <a href="/troubleshooting/quality-auto-downgrade.html">画质菜单与批量下载画质说明</a>；</li><li><strong>队列串行</strong>是刻意设计（防风控），同一时刻只有一个任务在下载，其余显示「排队中」；</li><li><strong>正在解析 / 下载时保存设置会中断这些任务</strong>（设置页会先提示）；</li><li>之前用 MP3 / FLAC 仅音频下载失败过的用户，现在可以再试了；</li><li><strong>疑难解答</strong>从应用内移到了本文档站点，应用内的入口会直接打开本站。</li></ul></div><h2 id="v2-1-0-2026-07-11" tabindex="-1">v2.1.0（2026-07-11） <a class="header-anchor" href="#v2-1-0-2026-07-11" aria-label="Permalink to &quot;v2.1.0（2026-07-11）&quot;">​</a></h2><p><strong>批量解析提速</strong></p><ul><li>内核升级至 uiya-yutto 0.1.0，合集 / 收藏夹批量解析并发执行，等待时间大幅缩短；</li><li>新增「解析并发数」设置项；</li><li>批量解析时单个视频失败不再中断整体任务；</li><li>VitePress 文档站点上线。</li></ul><h2 id="v2-0-2-2026-07-05" tabindex="-1">v2.0.2（2026-07-05） <a class="header-anchor" href="#v2-0-2-2026-07-05" aria-label="Permalink to &quot;v2.0.2（2026-07-05）&quot;">​</a></h2><p><strong>下载目录可配置与疑难解答</strong></p><ul><li>下载目录可独立配置，不再绑定根目录；</li><li>应用内疑难解答页面（v2.2.0 起移至本文档站点）；</li><li>音频格式选择（M4A / MP3 / FLAC / WAV）；</li><li>非首页懒加载，优化启动速度。</li></ul><h2 id="v2-0-1-2026-04-16" tabindex="-1">v2.0.1（2026-04-16） <a class="header-anchor" href="#v2-0-1-2026-04-16" aria-label="Permalink to &quot;v2.0.1（2026-04-16）&quot;">​</a></h2><p><strong>资源选择器与多平台构建</strong></p><ul><li>下载资源选择器（视频 / 音频 / 封面 / 字幕 / 弹幕）；</li><li>音频画质选项；</li><li>平台信息展示与一键 uv sync；</li><li>多平台 Release 构建流水线。</li></ul><h2 id="v2-0-0-2026-04-12" tabindex="-1">v2.0.0（2026-04-12） <a class="header-anchor" href="#v2-0-0-2026-04-12" aria-label="Permalink to &quot;v2.0.0（2026-04-12）&quot;">​</a></h2><p><strong>从 Streamlit 迁移至 Tauri</strong></p><ul><li>全新 Tauri 2 + React 桌面客户端；</li><li>全局快捷键呼出窗口；</li><li>合集 / 收藏夹批量解析与下载；</li><li>实时控制台日志；</li><li>扫码登录。</li></ul>',21)])])}const p=a(r,[["render",o]]);export{d as __pageData,p as default};
